const uvtY=y=>+((S.cfg.uvt||{})[y])||UVTD[y]||uvtHoy();
const BTIP=[['inmueble','Casa, apartamento o lote','house'],['vehiculo','Carro o moto','car'],['cuenta','Cuenta bancaria o efectivo','landmark'],['inversion','CDT, fondo o acciones','trending-up'],['cripto','Criptomonedas','bitcoin'],['exterior','Bien o cuenta en el exterior','globe'],['cobrar','Plata que te deben','hand-coins'],['otro','Otro bien','tag']];
const bienes=()=>{if(!Array.isArray(S.bienes))S.bienes=[];return S.bienes};
const titularId=()=>(S.perfil.miembros.find(m=>/titular/i.test(m.rol))||S.perfil.miembros[0]||{}).id||'familia';
RENTAY=today().getFullYear()-1;let RTAB='resumen',RQUIEN=null;
const rQuien=()=>RQUIEN||titularId();
function rData(y,mid){const Y=S.renta[y]||(S.renta[y]={docs:{},consig:0,consumos:0});Y.por=Y.por||{};if(!Y.por[mid]){Y.por[mid]={docs:mid===titularId()?{...(Y.docs||{})}:{},consig:mid===titularId()?+Y.consig||0:0,consumos:mid===titularId()?+Y.consumos||0:0,ing:{},ded:{}}}const R=Y.por[mid];R.ing=R.ing||{};R.ded=R.ded||{};R.docs=R.docs||{};return R}
const esDe=(x,mid)=>x.quien===mid||(mid===titularId()&&(!x.quien||x.quien==='familia'));
