const DEPR=[['hijo','Hijo o hija'],['conyuge','Cónyuge o pareja'],['padre','Padre o madre'],['hermano','Hermano o hermana']];
const edad=n=>{if(!n)return null;const b=parse(n),t=today();let a=t.getFullYear()-b.getFullYear();if(t<new Date(t.getFullYear(),b.getMonth(),b.getDate()))a--;return a};
function depInfo(m){const rel=m.depRel||(/hij/i.test(m.rol)?'hijo':/c[oó]nyuge|pareja/i.test(m.rol)?'conyuge':/padre|madre/i.test(m.rol)?'padre':/herman/i.test(m.rol)?'hermano':'');const e=edad(m.nac);let ok=false,why='';
 if(!m.depDe)return{rel,e,ok:false,why:'No marcado como dependiente'};
 if(rel==='hijo'){if(m.discap){ok=true;why='Hijo con dependencia por discapacidad'}else if(e===null){ok=true;why='Agrega la fecha de nacimiento para confirmar'}else if(e<18){ok=true;why=`Menor de 18 años (${e})`}else if(e<=23&&m.estudia){ok=true;why=`${e} años y estudia (educación superior o técnica)`}else why=e<=23?`${e} años: solo cuenta si estudia`:`${e} años: solo cuenta con discapacidad`}
 else if(rel==='conyuge'||rel==='padre'||rel==='hermano'){ok=!!m.sinIng||!!m.discap;why=ok?'Sin ingresos mayores a 260 UVT o con discapacidad':'Cuenta solo si no tuvo ingresos mayores a 260 UVT en el año'}
 else why='Este parentesco no da deducción';return{rel,e,ok,why}}
const depsDe=mid=>S.perfil.miembros.filter(m=>m.depDe===mid&&depInfo(m).ok);
// ---- cálculo ----
function tarifa241(u){if(u<=1090)return 0;if(u<=1700)return(u-1090)*.19;if(u<=4100)return(u-1700)*.28+116;if(u<=8670)return(u-4100)*.33+788;if(u<=18970)return(u-8670)*.35+2296;if(u<=31000)return(u-18970)*.37+5901;return(u-31000)*.39+10352}
function rentaAuto(y,mid){const sal=salarioDe(mid);const by=re=>S.ingresos.filter(x=>esDe(x,mid)&&re.test(x.cat+' '+x.concepto)&&!/salari/i.test(x.cat+' '+x.concepto)).reduce((a,x)=>a+mensual(x),0)*12;
 const hon=by(/honorar|independ|servicio|freelance|contrato/i),arr=by(/arriend/i),pen=by(/pensi[oó]n/i);const otr=S.ingresos.filter(x=>esDe(x,mid)&&!/salari|honorar|independ|servicio|freelance|contrato|arriend|pensi[oó]n/i.test(x.cat+' '+x.concepto)).reduce((a,x)=>a+mensual(x),0)*12;
 const fin=mid===titularId()?S.inversiones.reduce((a,x)=>a+inv(x).bruto,0):0,retInv=mid===titularId()?S.inversiones.reduce((a,x)=>a+inv(x).ret,0):0;
 const lab=sal*13,ces=sal*1.12;const fsp=sal?fspPct(sal)/100:0;const aportes=sal*12*(.08+fsp)+hon*.4*.285;let retLab=0;try{retLab=sal?retEmpleado(sal,sal*(.08+fsp))*12:0}catch(e){}
 return{lab,hon,ces,arr,fin,pen,otr,aportes:Math.round(aportes),ret:Math.round(retLab+retInv),volun:0,afc:0,sal}}
const RIK=[['lab','Salarios, primas y otros pagos laborales','Del certificado de ingresos y retenciones (formulario 220) de tu empleador.'],['hon','Honorarios o trabajo independiente','Lo que facturaste o te pagaron por servicios.'],['ces','Cesantías e intereses de cesantías','Lo que te consignaron en el año.'],['arr','Arriendos que recibiste','Total del año.'],['fin','Rendimientos financieros','Intereses de CDT, cuentas y fondos (certificados bancarios).'],['pen','Pensión','Si recibes pensión.'],['otr','Otros ingresos','Lo que no encaja arriba.'],['aportes','Aportes obligatorios a salud y pensión','Lo que te descontaron (o pagaste como independiente). No pagan impuesto.'],['volun','Aportes voluntarios a pensión','Certificado del fondo.'],['afc','Ahorro en cuentas AFC o AVC','Certificado del banco.'],['ret','Retenciones en la fuente que te hicieron','Suma de los certificados (empleador, bancos). Se restan del impuesto.']];
const RDK=[['intViv','Intereses del crédito de vivienda','Certificado del banco. Tope 1.200 UVT al año.',1200],['prep','Medicina prepagada o póliza de salud','Tope 16 UVT al mes (192 al año).',192],['gmf','4×1000 que pagaste (GMF)','Certificado bancario: se deduce el 50%.',null],['icetex','Intereses de crédito ICETEX','Tope 100 UVT al año.',100],['fe','Compras con factura electrónica pagadas con tarjeta o transferencia','Puedes restar el 1% (tope 240 UVT), fuera del límite del 40%.',null]];
function calcRenta(y,mid){const U=uvtY(y),A=rentaAuto(y,mid),R=rData(y,mid);const g=k=>R.ing[k]!==undefined&&R.ing[k]!==''&&R.ing[k]!==null?+R.ing[k]:A[k]||0;const dd=k=>+R.ded[k]||0;
 const lab=g('lab'),hon=g('hon'),ces=g('ces'),arr=g('arr'),fin=g('fin'),pen=g('pen'),otr=g('otr'),aportes=g('aportes'),volun=g('volun'),afc=g('afc'),ret=g('ret');
 const trabajo=lab+hon+ces,brutos=trabajo+arr+fin+otr+pen;const RL=Math.max(0,trabajo+arr+fin+otr-aportes);
 const salProm=A.sal||lab/13;const su=salProm/U;const cesPct=su<=350?1:su<=410?.9:su<=470?.8:su<=530?.6:su<=590?.4:su<=650?.2:0;const cesEx=ces*cesPct;
 const vol=Math.min(volun+afc,.3*(lab+hon),3800*U);const nD=depsDe(mid).length;
 const d10=nD?Math.min(.1*(lab+hon),384*U):0;const opA=d10+Math.min(Math.max(nD-1,0),4)*72*U,opB=Math.min(nD,4)*72*U;const useA=nD&&opA>=opB;const dep10=useA?d10:0,dep72=nD?(useA?Math.min(nD-1,4):Math.min(nD,4))*72*U:0;
 const intViv=Math.min(dd('intViv'),1200*U),prep=Math.min(dd('prep'),192*U),gmf=dd('gmf')*.5,icetex=Math.min(dd('icetex'),100*U);const fe=Math.min(dd('fe')*.01,240*U);
 const base25=Math.max(0,trabajo-aportes-(dep10+intViv+prep+gmf+icetex)-cesEx-vol);const r25=Math.min(base25*.25,790*U);
 const sub=cesEx+vol+dep10+intViv+prep+gmf+icetex+r25,lim=Math.min(.4*RL,1340*U),apl=Math.min(sub,lim);
 const penGrav=Math.max(0,pen-12000*U);const RLG=Math.max(0,RL-apl-dep72-fe)+penGrav;const impU=tarifa241(RLG/U);const imp=Math.round(impU*U/1000)*1000;const saldo=imp-ret;
 return{U,A,lab,hon,ces,arr,fin,pen,otr,aportes,volun,afc,ret,trabajo,brutos,RL,cesEx,cesPct,vol,nD,dep10,dep72,useA,intViv,prep,gmf,icetex,fe,r25,sub,lim,apl,recorte:sub-apl,RLG,imp,saldo}}
function patrimonio(mid){const tit=mid===titularId();const B=bienes().filter(b=>(b.duenio||titularId())===mid);const linked=new Set(B.map(b=>b.aid).filter(Boolean));
 const cuentas=tit?S.activos.filter(a=>/^11/.test(a.cod)&&!linked.has(a.id)).reduce((s,a)=>s+conv(a.valor,a.moneda),0):0,otrosAct=tit?S.activos.filter(a=>!/^11/.test(a.cod)&&!linked.has(a.id)).reduce((s,a)=>s+conv(a.valor,a.moneda),0):0;
 const invs=tit?S.inversiones.reduce((s,x)=>s+conv(inv(x).valor,x.moneda),0):0,cobr=tit?S.cobrar.reduce((s,L)=>s+engine(L).saldo,0):0;const bv=B.reduce((s,b)=>s+bValor(b)*(+b.pct||100)/100,0);
 const deudas=tit?S.pasivos.reduce((s,p)=>s+conv(p.valor,p.moneda),0)+S.pagar.reduce((s,L)=>s+engine(L).saldo,0):0;const bruto=cuentas+otrosAct+invs+cobr+bv;return{cuentas,otrosAct,invs,cobr,bv,bruto,deudas,liquido:bruto-deudas,B}}
const bValor=b=>b.tipo==='inmueble'?Math.max(+b.costo||0,+b.avaluo||0):(+b.valor31||+b.costo||+b.avaluo||0);
function topes(y,mid){const U=uvtY(y),C=calcRenta(y,mid),P=patrimonio(mid),R=rData(y,mid),yr=String(y);const tit=mid===titularId();
 const gas=tit?S.gastos.filter(g=>g.fecha.startsWith(yr)).reduce((a,g)=>a+ +g.valor,0):0,tc=tit?S.tarjetas.reduce((a,t)=>a+(t.compras||[]).filter(c=>c.fecha.startsWith(yr)).reduce((b,c)=>b+ +c.valor,0),0):0;
 return[['Ingresos brutos del año',C.brutos,1400,'Salario, primas, honorarios, arriendos, rendimientos…'],['Patrimonio bruto al 31 de diciembre',P.bruto,4500,'Todo lo que tienes: cuentas, inversiones, casa, carro, lo que te deben.'],['Compras con tarjeta de crédito',tc,1400,'Total pagado con tarjetas de crédito en el año.'],['Compras y consumos totales',Math.max(gas,+R.consumos||0),1400,'Todo lo que gastaste en el año.'],['Consignaciones y depósitos bancarios',+R.consig||0,1400,'Todo lo que te entró a tus cuentas en el año.']].map(([l,v,u,d])=>({l,v,u,d,tope:u*U,pasa:v>=u*U}))}
