 const bar=`<div class="card r-bar"><div class="form" style="grid-template-columns:repeat(auto-fit,minmax(200px,1fr))">${field('Año gravable',sel('ry',[2024,2025,2026].map(v=>({v,l:`${v} (declaras en ${v+1})`})),y,{attrs:'data-x="rentaY"'}))}${field('¿Quién declara?',sel('rq',S.perfil.miembros.filter(m=>m.id).map(m=>({v:m.id,l:`${m.nombre} · ${m.rol}`,icon:'user'})),mid,{attrs:'data-x="rentaQ"'}))}${field(`UVT ${y}`,money('ruvt',U,{attrs:`data-x="rentaUVT" data-y="${y}"`}),{tip:'Unidad que usa la DIAN para fijar topes y tarifas. 2024: $ 47.065 · 2025: $ 49.799 · 2026: $ 52.374.'})}</div></div>`;
