EXTRA_FORM.bien=(d,f)=>{if(!String(d.nombre||'').trim()){toast('Escribe el nombre del bien',{type:'warn'});return false}const o={tipo:d.tipo,nombre:d.nombre.trim(),ident:d.ident||'',entidad:d.entidad||'',costo:+d.costo||0,avaluo:+d.avaluo||0,valor31:+d.valor31||0,fechaAdq:d.fechaAdq||'',duenio:d.duenio||titularId(),pct:Math.min(100,Math.max(1,+d.pct||100)),predial:+d.predial||0,impVeh:+d.impVeh||0,soat:+d.soat||0};const ex=bienes().find(x=>x.id===f.dataset.id);if(ex)Object.assign(ex,o);else bienes().push({id:uid(),...o});toast(`${esc(o.nombre)} quedó en tus bienes.`,{type:'success',title:'Bien guardado'})};
