const unb64=s=>Uint8Array.from(atob(s),c=>c.charCodeAt(0));
const b64u=u=>b64(u).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,''),unb64u=s=>unb64(s.replace(/-/g,'+').replace(/_/g,'/')+'==='.slice((s.length+3)%4));
async function aesKey(raw){return crypto.subtle.importKey('raw',raw,'AES-GCM',false,['encrypt','decrypt'])}
async function encJSON(obj,raw){const iv=crypto.getRandomValues(new Uint8Array(12));let data=new TextEncoder().encode(JSON.stringify(obj)),gz=false;if(window.CompressionStream){data=new Uint8Array(await new Response(new Blob([data]).stream().pipeThrough(new CompressionStream('gzip'))).arrayBuffer());gz=true}const ct=await crypto.subtle.encrypt({name:'AES-GCM',iv},await aesKey(raw),data);return `${b64(iv)}.${b64(ct)}${gz?'.gz':''}`}
async function decJSON(s,raw){const [iv,ct,gz]=s.split('.');let pt=new Uint8Array(await crypto.subtle.decrypt({name:'AES-GCM',iv:unb64(iv)},await aesKey(raw),unb64(ct)));if(gz)pt=new Uint8Array(await new Response(new Blob([pt]).stream().pipeThrough(new DecompressionStream('gzip'))).arrayBuffer());return JSON.parse(new TextDecoder().decode(pt))}
async function verif(raw){const h=await crypto.subtle.digest('SHA-256',new Uint8Array([...raw,...new TextEncoder().encode('mirai-notas')]));return [...new Uint8Array(h)].map(x=>x.toString(16).padStart(2,'0')).join('')}
const accesos=()=>{S.dian=S.dian||{};S.dian.accesos=S.dian.accesos||[];return S.dian.accesos};
const accBase=()=>{const u=srvCfg().url;return(u||location.origin).replace(/\/$/,'')+'/'};
const accLink=a=>`${accBase()}?contador=${a.id}#k=${a.k}`;
function accSnapshot(a){const keep=a.perms==='todo'?Object.keys(S).filter(k=>!['chats','consejos','correoIds','calIds'].includes(k)):['v','perfil','ingresos','activos','pasivos','inversiones','cobrar','pagar','bienes','renta','calendario','tarjetas','gastos','fijos','cfg'];const o={};keep.forEach(k=>{if(S[k]!==undefined)o[k]=S[k]});if(a.perms!=='todo'){o.cfg={uvt:S.cfg.uvt,smmlv:S.cfg.smmlv,trm:S.cfg.trm,categorias:S.cfg.categorias};const yr=[String(RENTAY),String(RENTAY+1)];o.gastos=S.gastos.filter(g=>yr.some(y=>g.fecha.startsWith(y)))}
 if(o.dian)o.dian={...o.dian,accesos:[]};return{S:o,owner:S.perfil.nombre||'',perms:a.perms,at:new Date().toISOString()}}
async function accPush(a){const raw=unb64u(a.k);const blob=await encJSON(accSnapshot(a),raw);await srvFetch('/api/shares/'+a.id,{label:a.label,email:a.email,perms:a.perms,expires_at:a.exp||null,verifier:await verif(raw),blob},'PUT');a.push=new Date().toISOString()}
